Definition ATEXIT_FRAME : Z := 48.

Definition AtexitCells (slot head f0 a0 : Z) (f3 pad : list byte) (nx : Z) (fj aj : list byte) : list cell :=
  [C1 (b8 0); CB 3 f3; C4 (wz 0); C4 (wz slot); CB 4 pad; C8 (wz head); C8 (wz nx); C8 (wz f0); CB 248 fj; C8 (wz a0); CB 248 aj].

Lemma AtexitCells_size : forall slot head f0 a0 f3 pad nx fj aj,
  Z.of_nat (cells_size (AtexitCells slot head f0 a0 f3 pad nx fj aj)) = 544.
Proof. intros. reflexivity. Qed.

