Definition atexit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (fn : Z) (f3 pad : list byte) (nx : Z) (fj aj : list byte) (lo : Z) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (A_ATEXIT, A_ATEXIT + 544)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' A_ATEXIT (AtexitCells 1 A_ATEXIT_BUILTIN P_ATEXIT_CALL fn f3 pad nx fj aj).

Definition atexit_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : word -> option byte) (fn f0 a0v nx lo : Z) (f3 pad fj aj : list byte),
  rw_cells usegs m A_ATEXIT (AtexitCells 0 0 f0 a0v f3 pad nx fj aj) ->
  bytes_at usegs m A_NEED_LOCKS [b8 0] ->
  0 <= fn < 2^64 ->
  stk usegs m lo (bv_unsigned sp) -> lo + ATEXIT_FRAME <= bv_unsigned sp -> 0xb8000 <= lo ->
  mem_inv usegs m ->
  evt usegs (atexit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc fn f3 pad nx fj aj lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 fn) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ATEXIT) fc None m (seg_rom usegs)).
